package com.loadoutlab.data;

import com.google.gson.*;

// Where each mob is, for the Shortest Path link (ISS-01M5TCXDV8HF2V5C627SZEY2W3):
// mob_locations.json, generated by scripts/gen_mob_locations.py from the wiki;
// each point is packed as Shortest Path packs one (x | y << 15 | plane << 30).
public class MobLocations {
    static final JsonObject ALL = JsonResources.object("mob_locations.json");


    // The mob's spawn points, or null when nobody placed it.
    public static int[] of(String name) {
        JsonElement points = ALL.get(name.toLowerCase());
        return points == null ? null : JsonResources.ints(points.getAsJsonArray());
    }
}
